// Generate a small allocation size (kept reasonably small for fuzzer perf)
size_t size = (size_t)(*FUZZ_PARAM(unsigned int) % 1536);
// Call allocator; size==0 is allowed by API (may return NULL or non-NULL)
void *ptr = fio_malloc(size);
// Track allocator provenance and size for downstream APIs (free/realloc)
if (ptr) {
  FUZZ_SET_ATTR_STR(ptr, "alloc", "fio");
  FUZZ_SET_ATTR_INT(ptr, "size", (int)size);
  FUZZ_SET_ATTR_INT(ptr, "freed", 0);
}

// Choose unit size and count with tight bounds to avoid overflow and large allocs
size_t unit = (size_t)(*FUZZ_PARAM(unsigned int) % 64 + 1);
size_t count = (size_t)(*FUZZ_PARAM(unsigned int) % 32); // total <= ~2048 bytes
size_t prod = unit * count; // bounded above to avoid overflow here
void *ptr = fio_calloc(unit, count);
// Attach metadata for allocator provenance and logical size (product)
if (ptr) {
  FUZZ_SET_ATTR_STR(ptr, "alloc", "fio");
  FUZZ_SET_ATTR_INT(ptr, "size", (int)prod);
  FUZZ_SET_ATTR_INT(ptr, "freed", 0);
}

// ptr may be NULL; if non-NULL, ensure it came from this allocator and wasn't already freed
if (ptr) {
  const char *prov = FUZZ_GET_ATTR_STR(ptr, "alloc");
  int was_freed = FUZZ_GET_ATTR_INT(ptr, "freed");
  if (!prov[0] || was_freed) { FUZZ_BAIL(); }
}
// Free is safe on NULL as well
fio_free(ptr);
// Mark as freed to prevent double-free on reused handle
if (ptr) { FUZZ_SET_ATTR_INT(ptr, "freed", 1); }

// Determine new size (keep small)
size_t new_size = (size_t)(*FUZZ_PARAM(unsigned int) % 1536);
// Validate provenance of non-NULL input; NULL is allowed
if (ptr) {
  const char *prov = FUZZ_GET_ATTR_STR(ptr, "alloc");
  int was_freed = FUZZ_GET_ATTR_INT(ptr, "freed");
  if (!prov[0] || was_freed) { FUZZ_BAIL(); }
}
void *old_ptr = ptr;
void *new_ptr = fio_realloc(ptr, new_size);
if (!new_ptr) {
  // Realloc failed; original allocation remains valid and owned by caller
  // Keep returning the original pointer to the pool unchanged
  ptr = old_ptr;
} else {
  // Successful; if moved, invalidate old handle; if in-place, update metadata
  if (new_ptr != old_ptr) {
    if (old_ptr) { FUZZ_SET_ATTR_INT(old_ptr, "freed", 1); }
  }
  // Update ptr to new location and refresh metadata
  ptr = new_ptr;
  FUZZ_SET_ATTR_STR(ptr, "alloc", "fio");
  FUZZ_SET_ATTR_INT(ptr, "size", (int)new_size);
  FUZZ_SET_ATTR_INT(ptr, "freed", 0);
}

// Pick new_size and copy_length within tracked old size if available
size_t new_size = (size_t)(*FUZZ_PARAM(unsigned int) % 1536);
size_t copy_length = 0;
if (ptr) {
  const char *prov = FUZZ_GET_ATTR_STR(ptr, "alloc");
  int was_freed = FUZZ_GET_ATTR_INT(ptr, "freed");
  if (!prov[0] || was_freed) { FUZZ_BAIL(); }
  int old_sz = FUZZ_GET_ATTR_INT(ptr, "size");
  if (old_sz < 0) { FUZZ_BAIL(); }
  // Limit copy_length so it never exceeds old size per API requirement
  copy_length = (size_t)(*FUZZ_PARAM(unsigned int) % ( (size_t)old_sz + 1 ));
} else {
  // When ptr == NULL, copy_length must be 0 for semantic clarity
  copy_length = 0;
}
void *old_ptr = ptr;
void *new_ptr = fio_realloc2(ptr, new_size, copy_length);
if (!new_ptr) {
  // Failure leaves original allocation intact
  ptr = old_ptr;
} else {
  if (new_ptr != old_ptr) {
    if (old_ptr) { FUZZ_SET_ATTR_INT(old_ptr, "freed", 1); }
  }
  ptr = new_ptr;
  FUZZ_SET_ATTR_STR(ptr, "alloc", "fio");
  FUZZ_SET_ATTR_INT(ptr, "size", (int)new_size);
  FUZZ_SET_ATTR_INT(ptr, "freed", 0);
}

// Size must be > 0
size_t size = (size_t)(*FUZZ_PARAM(unsigned int) % 1536) + 1;
void *ptr = fio_mmap(size);
if (!ptr) { FUZZ_BAIL(); }
// Track as fio-managed so fio_free can release it later
FUZZ_SET_ATTR_STR(ptr, "alloc", "fio");
FUZZ_SET_ATTR_INT(ptr, "size", (int)size);
FUZZ_SET_ATTR_INT(ptr, "freed", 0);

// Avoid undefined behavior by using a fixed format string
std::string s = FUZZ_PARAM_STR();
unsigned v = *FUZZ_PARAM(unsigned int);
FIO_LOG2STDERR("msg:%s val:%u", s.c_str(), v);

// Open a random temporary file to obtain a valid fd
const char *path = FUZZ_PARAM_FILENAME();
int fd = -1;
// Use O_CREAT|O_RDWR to ensure an openable path; 0600 permissions
fd = open(path, 0x0002 | 0x0040, 0600);
if (fd < 0) { FUZZ_BAIL(); }
// Exercise the API; return value is OS-dependent and not asserted here
(void)fio_set_non_block(fd);
// Cleanup
close(fd);

// Query current capacity; no strong guarantees other than returning a size_t
size_t cap = fio_capa();
// Property: function must be side-effect free and return a value (including 0)
(void)cap;

// Prepare a fuzzed URL buffer; parser expects pointer+length and does not own memory
std::string url = FUZZ_PARAM_STR();
size_t use_len = url.size() ? (size_t)(*FUZZ_PARAM(unsigned int) % (url.size() + 1)) : 0;
// Call parser; returned slices reference the provided buffer
fio_url_s parts = fio_url_parse(url.data(), use_len);
// Basic property checks: all slices must either be NULL data with zero len or within bounds
// (Cannot dereference beyond provided buffer; here we only touch lengths.)
(void)parts;

// Request a cooperative shutdown of the facil.io application.
// Safe to call even if not running; in that case it should be a no-op per API.
fio_stop();
// Track that a stop was requested for possible cross-stub logic (optional).
FUZZ_SET_ATTR_INT_GLOBAL("stop_requested", 1);

// API requires non-NULL pointers; use local variables and pass their addresses.
int16_t threads = (int16_t)(*FUZZ_PARAM(unsigned int) % 16) - 8; // allow negatives/zero as callers might pass
int16_t workers = (int16_t)(*FUZZ_PARAM(unsigned int) % 16) - 8;
// Invoke; function overwrites provided values with expected ones.
fio_expected_concurrency(&threads, &workers);
// Store for potential downstream checks.
FUZZ_SET_ATTR_INT_GLOBAL("exp_threads", (int)threads);
FUZZ_SET_ATTR_INT_GLOBAL("exp_workers", (int)workers);

// Query running state; value semantics defined by API (0 when not running).
int16_t running = fio_is_running();
(void)running;

// Returns 1 if in worker or single-process instance, else 0.
int flag = fio_is_worker();
FUZZ_ASSERT(flag == 0 || flag == 1, "fio_is_worker must return 0 or 1");

// Returns 1 if current process is the master (root) process, else 0.
int flag = fio_is_master();
FUZZ_ASSERT(flag == 0 || flag == 1, "fio_is_master must return 0 or 1");

// Returns facil.io's parent (root) process PID.
pid_t p = fio_parent_pid();
(void)p;

// Should be called before fio_start; harmless if called multiple times.
fio_reap_children();
// Record for potential follow-up logic.
FUZZ_SET_ATTR_INT_GLOBAL("reap_enabled", 1);

// Obtain the last tick time and check basic invariants for timespec range.
struct timespec ts = fio_last_tick();
FUZZ_ASSERT(ts.tv_nsec >= 0, "timespec tv_nsec negative");
FUZZ_ASSERT(ts.tv_nsec < 1000000000L, "timespec tv_nsec out of range");
(void)ts;

// Returns a C-string naming the IO engine; should be a valid pointer to a NUL-terminated string.
const char *name = fio_engine();
FUZZ_ASSERT(name != NULL, "fio_engine returned NULL");
// Best-effort sanity: first byte should be printable ASCII for known engines.
FUZZ_ASSERT(name[0] != '\0', "fio_engine returned empty string");

// Prepare a writable buffer; limit must be > 0 per API. Keep small for fuzzer perf.
size_t limit = ((size_t)(*FUZZ_PARAM(unsigned int) % 256)) + 1; // [1,256]
std::string buf;
buf.resize(limit);
size_t written = fio_local_addr(&buf[0], limit);
// Contract: if written == limit - 1, output may be truncated; always exclude the NUL terminator.
FUZZ_ASSERT(written <= (limit ? (limit - 1) : 0), "fio_local_addr wrote beyond limit-1");
// Optional: ensure resulting buffer remains a valid C string at buf[written] when space permits.
if (limit) { (void)buf[written]; }

// Exercise the no-op deallocator with a valid non-null pointer.
// Use a small local buffer to avoid any ownership confusion.
unsigned char local_buf[32] = {0};
void *p = (void *)local_buf;
FIO_DEALLOC_NOOP(p);
// Validation: no crash and no side-effects expected.

// Attempt to flush all connections; valid even if none exist.
size_t remaining = fio_flush_all();
(void)remaining; // No strong guarantees; just ensure the call is exercised.
// Validation: function returns a count; no preconditions to enforce here.

// Open a temporary file to obtain a valid OS file descriptor.
const char *path = FUZZ_PARAM_FILENAME();
int fd = open(path, 0x0002 | 0x0040, 0600); // O_RDWR | O_CREAT
if (fd < 0) { FUZZ_BAIL(); }
// Map fd to a facil.io uuid. This may return -1 if fd isn't registered with facil.io.
intptr_t uuid = fio_fd2uuid(fd);
(void)uuid;
close(fd);
// Validation: fd was valid; api may return -1 legitimately when unregistered.

// Perform any pending deferred tasks. Safe even if none are queued.
fio_defer_perform();
// Validation: no arguments and no preconditions; call must be safe.

// Query whether deferred tasks are pending; no preconditions.
int has = fio_defer_has_queue();
(void)has;
// Validation: function is side-effect free and returns an int flag; nothing to assert beyond successful call.

// Pick a random lifecycle event type in range [0,13].
int type_idx = (int)(*FUZZ_PARAM(unsigned int) % 14);
callback_type_e type = (callback_type_e)type_idx;
// Use an existing compatible function pointer for callbacks; FIO_DEALLOC_NOOP matches void (*)(void*).
void (*cb)(void*) = FIO_DEALLOC_NOOP;
void *arg = NULL; // opaque argument; may be NULL
