import random
import string
from typing import List, Tuple

# Data type: URL string
# Targets:
# - fio_url_parse(url_ptr, length): accepts a pointer to a buffer and an explicit length; slices reference the buffer.
# - websocket_connect(url_cstr, settings): expects a NUL-terminated C string with a ws:// or wss:// URL.
#
# Strategy:
# - Produce a single buffer that contains one or more newline-separated URL candidates. The fuzzer harness pulls a
#   std::string via FUZZ_PARAM_STR; providing multiple candidates increases chance different substrings/lengths are used.
# - Include a rich variety of valid yet diverse URL shapes covering: schemes, auth, IPv4, IPv6 (with brackets),
#   ports (incl. edge cases 0, 65535), paths, queries, fragments, percent-encoding, userinfo with special chars,
#   Unicode (UTF-8), long paths, empty paths, absolute-path-only, host:port without scheme, and WebSocket-specific paths.
# - Limit output to <= 4096 bytes.

SCHEMES = [
    "http", "https", "ws", "wss", "ftp", "file", "redis", "amqp",
]

USER_PARTS = [
    "user", "user.name", "u-ser", "%75ser", "😀", "", "alice", "bob",
]
PASS_PARTS = [
    "pass", "p@ss:word", "", "%32%41", "🔒",
]

HOSTS = [
    "localhost", "example.com", "sub.domain.example", "xn--bcher-kva.example",  # punycode-like label
    "0.0.0.0", "127.0.0.1", "255.255.255.255",
]

IPV6S = [
    "::1", "2001:db8::1", "fe80::1%eth0", "2001:0db8:85a3:0000:0000:8a2e:0370:7334",
]

PATH_SEGMENTS = [
    "", "/", "/index.html", "/ws", "/chat", "/a/b/c", "/%2Fweird", "/😀/路径", "/long/" + "a"*64,
]

QUERIES = [
    "", "?", "?q=1", "?q=hello+world", "?q=100&x=200", "?name=J%C3%B6rg", "?token=abc.def%2Fghi",
]

FRAGMENTS = [
    "", "#", "#top", "#🔗",
]

PORTS: List[int] = [0, 1, 80, 443, 65535, 8080, 3000, 6379]

WS_PATHS = ["/", "/chat", "/ws", "/socket", "/echo", "/api/v1/events"]

SAFE_CHARS = string.ascii_letters + string.digits + "-._~"


def rand_choice(rnd: random.Random, arr: List):
    return arr[rnd.randrange(len(arr))]


def build_userinfo(rnd: random.Random) -> str:
    if rnd.random() < 0.5:
        return ""
    user = rand_choice(rnd, USER_PARTS)
    # 50% include password
    if rnd.random() < 0.5:
        pw = rand_choice(rnd, PASS_PARTS)
        return f"{user}:{pw}@"
    return f"{user}@"


def build_host(rnd: random.Random) -> str:
    t = rnd.random()
    if t < 0.6:
        return rand_choice(rnd, HOSTS)
    elif t < 0.9:
        ip6 = rand_choice(rnd, IPV6S)
        # Bracket IPv6 for URL host syntax; zone IDs stay inside brackets
        return f"[{ip6}]"
    else:
        # Random-ish hostname label chain
        labels = []
        for _ in range(rnd.randint(2, 4)):
            l = ''.join(rnd.choice(SAFE_CHARS) for _ in range(rnd.randint(1, 10))).lower()
            labels.append(l)
        return ".".join(labels)


def build_port(rnd: random.Random) -> str:
    if rnd.random() < 0.6:
        return ""
    if rnd.random() < 0.7:
        p = rand_choice(rnd, PORTS)
    else:
        p = rnd.randint(1, 65535)
    return f":{p}"


def build_path(rnd: random.Random) -> str:
    if rnd.random() < 0.7:
        return rand_choice(rnd, PATH_SEGMENTS)
    # Compose random multi-segment path with some percent-encoding
    segs = []
    for _ in range(rnd.randint(1, 5)):
        if rnd.random() < 0.4:
            seg = ''.join(rnd.choice(SAFE_CHARS) for _ in range(rnd.randint(0, 12)))
        else:
            # include percent-encoded bytes
            raw = rnd.randbytes(rnd.randint(0, 6)) if hasattr(rnd, 'randbytes') else bytes(
                [rnd.randrange(256) for _ in range(rnd.randint(0, 6))]
            )
            seg = ''.join(f"%{b:02X}" for b in raw)
        segs.append(seg)
    return "/" + "/".join(segs)


def build_query(rnd: random.Random) -> str:
    if rnd.random() < 0.6:
        return rand_choice(rnd, QUERIES)
    # k=v pairs, url-encoded-ish
    pairs = []
    for _ in range(rnd.randint(1, 4)):
        k = ''.join(rnd.choice(SAFE_CHARS) for _ in range(rnd.randint(1, 8)))
        v = ''.join(rnd.choice(SAFE_CHARS + "+%") for _ in range(rnd.randint(0, 12)))
        pairs.append(f"{k}={v}")
    return "?" + "&".join(pairs)


def build_fragment(rnd: random.Random) -> str:
    if rnd.random() < 0.7:
        return rand_choice(rnd, FRAGMENTS)
    txt = ''.join(rnd.choice(SAFE_CHARS) for _ in range(rnd.randint(0, 12)))
    return f"#{txt}"


def build_full_url(rnd: random.Random, force_ws: bool = False) -> str:
    scheme = "ws" if force_ws and rnd.random() < 0.5 else ("wss" if force_ws else rand_choice(rnd, SCHEMES))
    auth = build_userinfo(rnd)
    host = build_host(rnd)
    port = build_port(rnd)
    path = rand_choice(rnd, WS_PATHS) if force_ws and rnd.random() < 0.7 else build_path(rnd)
    query = build_query(rnd)
    frag = build_fragment(rnd)
    return f"{scheme}://{auth}{host}{port}{path}{query}{frag}"


def build_host_port_only(rnd: random.Random) -> str:
    host = build_host(rnd)
    port = build_port(rnd)
    if not port:
        port = f":{rand_choice(rnd, PORTS)}"
    return f"{host}{port}"


def build_path_only(rnd: random.Random) -> str:
    # Absolute path per RFC 3986 path-absolute
    path = build_path(rnd)
    if not path or not path.startswith('/'):
        path = "/" + path
    return path + build_query(rnd) + build_fragment(rnd)


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    urls: List[str] = []

    # 1) A few guaranteed valid ws/wss URLs for websocket_connect
    for _ in range(3):
        urls.append(build_full_url(rnd, force_ws=True))

    # 2) Mixed scheme URLs for fio_url_parse coverage
    for _ in range(6):
        urls.append(build_full_url(rnd, force_ws=False))

    # 3) Host:port without scheme
    for _ in range(3):
        urls.append(build_host_port_only(rnd))

    # 4) Absolute-path only
    for _ in range(3):
        urls.append(build_path_only(rnd))

    # 5) Edge cases: empty, just scheme, scheme://, IPv6 with port, userinfo only before host, long path
    urls.extend([
        "",  # empty buffer (parser should handle length=0)
        "ws://",  # minimal with scheme
        "wss://[::1]:443/",  # IPv6 + port
        "http://user:@example.com/",  # user with empty password
        "ftp://%75ser:p%40ss@example.com:21/home",  # percent-encoding in userinfo
        "http://example.com/" + "a" * 512,  # long path
    ])

    # 6) Produce some URLs with fragments only or queries only after host
    urls.append("https://example.com?only=query")
    urls.append("https://example.com#onlyfrag")

    # Shuffle for diversity
    rnd.shuffle(urls)

    # Join as newline-separated candidates; harness will likely use the whole string or parts
    blob = ("\n".join(urls)).encode("utf-8", errors="surrogatepass")

    # Truncate to 4096 bytes to respect fuzzer input limit
    if len(blob) > 4096:
        blob = blob[:4096]

    return blob

