    # Choose alphabet and encode
    use_url = r.random() < 0.4
    if use_url:
        enc = base64.urlsafe_b64encode(raw).decode()
    else:
        enc = base64.b64encode(raw).decode()

    # Optional manipulations to reflect lenient decoder behavior
    if r.random() < 0.5:
        enc = _maybe_strip_padding(r, enc)
    if r.random() < 0.3:
        enc = _chunk_with_newlines(r, enc)
    if r.random() < 0.3:
        enc = _insert_whitespace(r, enc)
    if r.random() < 0.3:
        enc = _mix_invalid_ignored(r, enc)
    if not use_url and r.random() < 0.2:
        # Convert some standard encodings to URL-safe post-hoc
        enc = _to_urlsafe(r, enc)

    # Sometimes return deliberately empty or minimal strings
    specials: List[str] = [
        "",  # empty input
        "=", "==",  # just padding
        "A", "AA", "AAA", "AAAA",  # short groups
        "-", "_", "+/", "-/",  # single alphabet chars
        "\n\r\n",  # whitespace only
    ]
    if r.random() < 0.15:
        enc = r.choice(specials)

    # Ensure output fits size limit and return bytes
    b = enc.encode()
    return b[:4096]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Optionally concatenate multiple encoded parts with whitespace between to test skipping
    parts = []
    num_parts = 1 if r.random() < 0.7 else r.randint(2, 5)
    for _ in range(num_parts):
        parts.append(_build_case(r))
    sep = r.choice([b"", b"\n", b"\r\n", b" ", b"\t"]) if len(parts) > 1 else b""
    data = sep.join(parts)
    return data[:4096]
